import type {LiveTransport} from '../../listen-upstream/realtime/transport'
import {nativeSegment} from '../../listen-upstream/continuous/segments'
import {ListenReservationAudioCache} from '../listen-reservation-cache'
import {loopPosition,type LoopExit} from './loop-contract'
import {LoopCatalog,type LoopPrepared} from './loop-catalog'
import {LoopGraph} from './loop-graph'
type Deck=NonNullable<LiveTransport['active']>
type Host=Pick<LiveTransport,'ctx'|'cache'|'active'|'position'|'playing'|'tracks'|'busy'|'pending'|'gate'|'status'|'log'|'cancelPreparation'>&{crossGenrePending?:unknown;liveLayeringPending?:unknown}
type Seam={monitor:AudioWorkletNode;graph:(t:Deck['track'],at:number,offset:number)=>Deck;nativeSource:(d:Deck,b:AudioBuffer,at:number,offset:number,edge:boolean)=>void;retire:(d:Deck,fade:boolean)=>void;protected:()=>void}
export class LoopSession{
 enabled=false;cycles=4;revision=0;private used=new Set<string>();private preparing:AbortController|null=null;private ready:LoopPrepared|null=null;private source:Deck|null=null;private state='disabled';private reason='器乐循环已关闭';private generation=0;private retryAt=0;private owner:ListenReservationAudioCache;private tails:{graph:LoopGraph;ready:LoopPrepared;until:number}[]=[]
 pending:{plan:{id:string;from:string;to:string;start:number;end:number;entry:number;family:'loop-extension'};source:Deck;deck:Deck;start:number;end:number;graph:LoopGraph;prepared:LoopPrepared;restore:()=>void;silenced:boolean}|null=null
 constructor(private host:Host,private base:URL,private notify:()=>void,private catalog=new LoopCatalog(host.ctx,host.cache,base)){this.owner=new ListenReservationAudioCache(host.ctx,base,()=>{},host.cache.pool)}
 configure(enabled:boolean,cycles=4){if(![4,8,16].includes(cycles))throw Error('循环次数只支持 4、8、16');if(this.pending){if(enabled)throw Error('循环释放后再调整次数');this.enabled=false;if(!this.cancel())this.release();return}this.cancelPreparation();this.enabled=enabled;this.retryAt=0;this.cycles=cycles;this.state=enabled?'idle':'disabled';this.reason=enabled?'等待本曲已批准的器乐循环':'器乐循环已关闭';this.notify()}
 cancelPreparation(){this.generation++;this.preparing?.abort();this.preparing=null;this.ready?.release();this.ready=null;this.source=null}
 async warm(){if(!this.enabled||this.pending||this.ready||this.preparing||Date.now()<this.retryAt||!this.host.active)return;const a=this.host.active;if(this.used.has(a.track.id))return;const c=this.preparing=new AbortController(),g=this.generation;this.state='preparing';this.reason='准备循环与两个相位的原曲恢复片段';this.notify();const check=()=>{c.signal.throwIfAborted();if(g!==this.generation||a!==this.host.active||!this.enabled)throw new DOMException('循环准备取消','AbortError')}
  try{const rows=await this.catalog.candidates(a.track,this.host.position,c.signal);check();let error:unknown;for(const row of rows.slice(0,4)){try{const r=await this.catalog.prepare(row,a.track,()=>this.host.position,c.signal);try{check()}catch(e){r.release();throw e}this.ready=r;this.source=a;this.state='ready';this.reason='循环已准备，将在原曲合适位置进入';this.notify();return}catch(e){check();error=e}}if(!rows.length)this.used.add(a.track.id);throw error??Error('本曲没有通过检查的未来器乐循环')
  }catch(e){if(g===this.generation){this.retryAt=Date.now()+3000;this.state='unavailable';this.reason=(e as Error).message+'；普通混音继续';this.host.log('loop_preparation_unavailable',{reason:this.reason})}}finally{if(this.preparing===c)this.preparing=null;this.notify()}}
 get upcoming(){return this.source===this.host.active?this.ready:null}
 get position(){const p=this.pending;return p&&this.host.ctx.currentTime>=p.start?loopPosition(p.prepared.approval,this.host.ctx.currentTime-p.start):null}
 private body(r:LoopPrepared,e:LoopExit,at:number){const seam=this.host as unknown as Seam,position=e.sourceFrame/44100,asset=nativeSegment(r.track,position).asset,b=r.bodyBuffers.get(asset.url);if(!b)throw Error('循环释放素材未准备');const d=seam.graph(r.track,at,position);try{d.gain.gain.value=0;seam.nativeSource(d,b,at,position,false);d.gain.gain.setValueAtTime(0,at);d.gain.gain.linearRampToValueAtTime(.76,at+.008);return d}catch(e){seam.retire(d,false);throw e}}
 arm(){const r=this.upcoming,a=this.host.active;if(!r||!a||!this.enabled||this.pending||!this.host.playing||this.host.busy||this.host.pending||this.host.crossGenrePending||this.host.liveLayeringPending||this.host.gate.locked)return false;const start=r.approval.startFrame/44100,lead=start-this.host.position;if(lead<.4){this.cancelPreparation();return false}const at=this.host.ctx.currentTime+lead,seam=this.host as unknown as Seam;let graph:LoopGraph|undefined,deck:Deck|undefined;const original=a.stream
  try{const exit={atFrame:this.cycles*r.approval.lengthFrames,sourceFrame:r.approval.startFrame+r.approval.lengthFrames};deck=this.body(r,exit,at+exit.atFrame/44100);graph=new LoopGraph(this.host.ctx,seam.monitor,r,a.gain.gain,at,this.cycles);let silenced=false;const self=this,proxy=original?new Proxy(original,{get(t,k){if(k==='deadline'&&(self.pending?.silenced||silenced||t.deadline>=at+.008-1/44100))return Infinity;if(k==='pins'&&silenced)return new Set<string>();const v=Reflect.get(t,k,t);return typeof v==='function'?v.bind(t):v}}):null;if(proxy)a.stream=proxy
   this.pending={plan:{id:r.approval.id,from:a.track.id,to:a.track.id,start,end:start+exit.atFrame/44100,entry:exit.sourceFrame/44100,family:'loop-extension'},source:a,deck,start:at,end:at+exit.atFrame/44100,graph,prepared:r,restore:()=>{silenced=true;if(a.stream===proxy)a.stream=original},silenced:false};this.ready=null;this.source=null;this.state='armed';this.owner.protected=new Set(r.bodyBuffers.keys());this.host.log('loop_extension_scheduled',{id:r.approval.id,sourceAnchor:start,contextStart:at,cycles:this.cycles,loopFrames:r.approval.lengthFrames,workspaceBytes:r.buffer.length*8,continuation:exit.sourceFrame/44100,renderRequested:false});this.notify();return true
  }catch(e){graph?.cancel();if(deck)seam.retire(deck,false);this.cancelPreparation();this.reason=(e as Error).message;this.notify();return false}}
 release(){const p=this.pending;if(!p)return false;const e=p.graph.nextExit(this.cycles);if(!e||e.atFrame>=p.graph.exit.atFrame)return true;let deck:Deck|undefined;try{deck=this.body(p.prepared,e,p.start+e.atFrame/44100);p.graph.setExit(e);(this.host as unknown as Seam).retire(p.deck,false);p.deck=deck;p.end=p.start+e.atFrame/44100;p.plan.entry=e.sourceFrame/44100;p.plan.end=p.plan.start+e.atFrame/44100;this.state='exiting';this.reason='将在最近获准点释放循环，从对应原曲位置继续';this.host.log('loop_release_selected',{id:p.plan.id,...e});this.notify();return true}catch(e){if(deck)(this.host as unknown as Seam).retire(deck,false);this.host.log('loop_release_unavailable',{reason:(e as Error).message});return false}}
 tick(){if(this.ready&&this.source!==this.host.active)this.cancelPreparation();const now=this.host.ctx.currentTime;for(const t of this.tails)if(now>=t.until){t.graph.stop();t.ready.release()}this.tails=this.tails.filter(t=>now<t.until);const p=this.pending;if(!p)return;if(this.host.active!==p.source){this.stop();return}p.deck.stream?.pump();this.owner.protected=new Set([...p.prepared.bodyBuffers.keys(),...p.deck.stream?.pins??[]]);if(now>=p.start-.15)this.host.gate.locked=true
  if(now>=p.start+.008&&!p.silenced){p.silenced=true;p.source.stream?.dispose();for(const n of p.source.sources)try{n.stop()}catch{}}
  if(now>=p.end+.008){const seam=this.host as unknown as Seam;this.host.active=p.deck;p.deck.at=p.end;p.deck.offset=p.plan.entry;p.restore();seam.retire(p.source,false);this.pending=null;this.host.gate.locked=false;this.owner.protected.clear();this.tails.push({graph:p.graph,ready:p.prepared,until:p.end+.02});seam.protected();this.used.add(p.source.track.id);this.revision++;this.state=this.enabled?'idle':'disabled';this.reason='循环释放完成，原曲继续；下一首保持原有混音规则';this.host.log('loop_extension_complete',{id:p.plan.id,sourcePosition:p.plan.entry,cycles:p.graph.exit.atFrame/p.prepared.approval.lengthFrames});this.notify()}}
 cancel(){const p=this.pending;if(!p)return true;if(this.host.ctx.currentTime>=p.start-.15)return false;p.restore();p.graph.cancel();(this.host as unknown as Seam).retire(p.deck,false);p.prepared.release();this.pending=null;this.host.gate.locked=false;this.owner.protected.clear();return true}
 stop(){this.cancelPreparation();if(this.pending){const p=this.pending;this.pending=null;p.restore();p.graph.stop();(this.host as unknown as Seam).retire(p.deck,false);p.prepared.release()}for(const t of this.tails){t.graph.stop();t.ready.release()}this.tails=[];this.used.clear();this.owner.protected.clear();this.host.gate.locked=false}
 snapshot(){const p=this.pending,r=p?.prepared??this.upcoming,elapsed=p?Math.max(0,this.host.ctx.currentTime-p.start):0;return{enabled:this.enabled,cycles:this.cycles,revision:this.revision,state:p?(this.state==='exiting'?'exiting':this.host.ctx.currentTime>=p.start?'playing':'armed'):this.state,reason:this.reason,start:r?r.approval.startFrame/44100:undefined,completedCycles:r?Math.floor(elapsed*44100/r.approval.lengthFrames):0,duration:r?this.cycles*r.approval.lengthFrames/44100:undefined}}
 dispose(){this.stop();this.owner.dispose();this.catalog.dispose()}
}
